@Component
export struct NotePreviewPage {
  @State preview: string = ''
  private drafts: DraftRepository
  async reloadPreview(): Promise<void> {
    this.preview = await this.drafts.readPreview()
  }
  build() {
    Text(this.preview)
  }
}

